user_pref("nimbus.syncdefaultsstore.aboutwelcome", "{\"slug\":\"rollout-npo-account-login-screen-windows-select-locales\",\"branch\":{\"slug\":\"treatment-a\",\"ratio\":1,\"feature\":{\"value\":null,\"enabled\":true,\"featureId\":\"aboutwelcome\"},\"features\":null,\"firefoxLabsTitle\":null},\"active\":true,\"experimentType\":\"rollout\",\"source\":\"rs-loader\",\"userFacingName\":\"Rollout - NPO Account Login Screen Windows Select Locales\",\"userFacingDescription\":\"This experiment changes the onboarding experience to present a screen that allows the user to login or signup with a Mozilla account.\",\"lastSeen\":\"2024-11-30T14:41:39.558Z\",\"featureIds\":[\"aboutwelcome\"],\"prefs\":[],\"localizations\":{\"de\":{\"onboarding-sign-up-title\":\"Synchronisiere deine Daten zwischen Geräten\",\"onboarding-sign-up-button\":\"Anmelden oder registrieren\",\"onboarding-sign-up-description\":\"Melde dich für ein Konto an und all deine wichtigen Infos – Passwörter, Lesezeichen und mehr – werden sicher gespeichert und sind verfügbar, wenn du dich auf irgendeinem Gerät anmeldest.\"},\"fr\":{\"onboarding-sign-up-title\":\"Synchronisez vos données entre vos appareils\",\"onboarding-sign-up-button\":\"S’inscrire ou se connecter\",\"onboarding-sign-up-description\":\"Créez un compte et toutes vos informations importantes (mots de passe, marque-pages, et plus encore) seront stockées en toute sécurité et disponibles lorsque vous vous connecterez sur n’importe quel appareil.\"},\"it\":{\"onboarding-sign-up-title\":\"Sincronizza i tuoi dati su tutti i dispositivi\",\"onboarding-sign-up-button\":\"Registrati o accedi\",\"onboarding-sign-up-description\":\"Crea un account e tutte le tue informazioni più importanti (password, segnalibri e altro ancora) saranno archiviate in modo sicuro e disponibili quando accedi da qualsiasi dispositivo.\"},\"ru\":{\"onboarding-sign-up-title\":\"Синхронизируйте свои данные на всех устройствах\",\"onboarding-sign-up-button\":\"Зарегистрироваться или войти\",\"onboarding-sign-up-description\":\"Зарегистрируйте аккаунт, и вся ваша важная информация — пароли, закладки и многое другое — будет надежно храниться и доступна после входа в систему на любом устройстве.\"},\"en-CA\":{\"onboarding-sign-up-title\":\"Sync your data across devices\",\"onboarding-sign-up-button\":\"Sign up or sign in\",\"onboarding-sign-up-description\":\"Sign up for an account and all of your important info — passwords, bookmarks, and more — will be securely stored and available when you sign in to any device.\"},\"en-GB\":{\"onboarding-sign-up-title\":\"Sync your data across devices\",\"onboarding-sign-up-button\":\"Sign up or sign in\",\"onboarding-sign-up-description\":\"Sign up for an account and all of your important info — passwords, bookmarks, and more — will be securely stored and available when you sign in to any device.\"},\"en-US\":{\"onboarding-sign-up-title\":\"Sync your data across devices\",\"onboarding-sign-up-button\":\"Sign up or sign in\",\"onboarding-sign-up-description\":\"Sign up for an account and all of your important info — passwords, bookmarks, and more — will be securely stored and available when you sign in to any device.\"},\"es-AR\":{\"onboarding-sign-up-title\":\"Sincroniza tus datos entre dispositivos\",\"onboarding-sign-up-button\":\"Regístrate o inicia sesión\",\"onboarding-sign-up-description\":\"Regístrate para obtener una cuenta y toda tu información importante (contraseñas, marcadores y más) se guardará de forma segura y estará disponible cuando inicies sesión en cualquier dispositivo.\"},\"es-CL\":{\"onboarding-sign-up-title\":\"Sincroniza tus datos entre dispositivos\",\"onboarding-sign-up-button\":\"Regístrate o inicia sesión\",\"onboarding-sign-up-description\":\"Regístrate para obtener una cuenta y toda tu información importante (contraseñas, marcadores y más) se guardará de forma segura y estará disponible cuando inicies sesión en cualquier dispositivo.\"},\"es-ES\":{\"onboarding-sign-up-title\":\"Sincroniza tus datos entre dispositivos\",\"onboarding-sign-up-button\":\"Regístrate o inicia sesión\",\"onboarding-sign-up-description\":\"Regístrate para obtener una cuenta y toda tu información importante (contraseñas, marcadores y más) se guardará de forma segura y estará disponible cuando inicies sesión en cualquier dispositivo.\"},\"es-MX\":{\"onboarding-sign-up-title\":\"Sincroniza tus datos entre dispositivos\",\"onboarding-sign-up-button\":\"Regístrate o inicia sesión\",\"onboarding-sign-up-description\":\"Regístrate para obtener una cuenta y toda tu información importante (contraseñas, marcadores y más) se guardará de forma segura y estará disponible cuando inicies sesión en cualquier dispositivo.\"}},\"isRollout\":true}");
